"""Pack the user's PET UI reference crops as allocation-free monochrome icons."""
from pathlib import Path
import hashlib
import json

from PIL import Image, ImageOps

ROOT = Path(__file__).resolve().parents[2]
ASSETS = ROOT / "assets_local/pet/ui"


def main():
    metadata = json.loads((ASSETS / "reference-icons.json").read_text("utf-8"))
    lines = ["#pragma once", "", "#include <Icon.h>", "",
             "// Generated by tools_local/pet/build_reference_icons.py from the supplied references.",
             "namespace petui::referenceicons {", "// clang-format off"]
    total = 0
    for name, spec in metadata.items():
        source = ASSETS / spec["source"]
        assert hashlib.sha256(source.read_bytes()).hexdigest() == spec["source_sha256"], name
        original = Image.open(source).convert("L")
        left, top, right, bottom = spec["crop"]
        assert 0 <= left < right <= original.width and 0 <= top < bottom <= original.height, name
        crop = original.crop(spec["crop"])
        if spec.get("invert"):
            crop = ImageOps.invert(crop)
        for box in spec.get("clear", []):
            crop.paste(255, box)
        for patch in spec.get("copy", []):
            x1, y1, x2, y2 = patch["crop"]
            x, y = patch["at"]
            assert 0 <= x1 < x2 <= original.width and 0 <= y1 < y2 <= original.height, name
            assert 0 <= x <= crop.width - (x2 - x1) and 0 <= y <= crop.height - (y2 - y1), name
            piece = original.crop(patch["crop"])
            if spec.get("invert"):
                piece = ImageOps.invert(piece)
            crop.paste(piece, (x, y))
        crop = crop.point(lambda v: 255 if v >= 128 else 0, mode="1")
        bounds = ImageOps.invert(crop.convert("L")).getbbox()
        assert bounds, name
        crop = crop.crop(bounds)
        width, height = spec["size"]
        assert width > 0 and height > 0 and width % 8 == 0, name
        crop.thumbnail((width - 2, height - 2), Image.Resampling.NEAREST)
        canvas = Image.new("1", (width, height), 1)
        canvas.paste(crop, ((width - crop.width) // 2, (height - crop.height) // 2))
        data = canvas.tobytes()
        total += len(data)
        lines.append(f"inline constexpr uint8_t {name}_BITS[] = {{")
        for at in range(0, len(data), 16):
            lines.append("    " + ", ".join(f"0x{v:02x}" for v in data[at:at + 16]) + ",")
        lines.extend(["};", f"inline constexpr freeink::Icon {name} = {{{width}, {height}, {height // 2}, {name}_BITS}};", ""])
    lines.extend(["// clang-format on", "}  // namespace petui::referenceicons", ""])
    (ROOT / "src/apps_local/pet/PetReferenceIcons.h").write_text("\n".join(lines), "utf-8")
    print(f"Packed {len(metadata)} reference icons: {total} flash bitmap bytes")


if __name__ == "__main__":
    main()
